code.java:
class Solution {
    public boolean isSubsequence(String s,String t){
        int matched=0;
        for(int i=0;i<t.length()&&matched<s.length();i++)if(t.charAt(i)==s.charAt(matched))matched++;
        return matched==s.length();
    }
}

code.kotlin:
class Solution {
    fun isSubsequence(s:String,t:String):Boolean{
        var matched=0;
        for(c in t)if(matched<s.length&&c==s[matched])matched++;
        return matched==s.length
    }
}

code.cpp:
class Solution {
    public: bool isSubsequence(string s,string t){
        int matched=0;
        for(char c:t)if(matched<(int)s.size()&&c==s[matched])++matched;
        return matched==(int)s.size();
    }
};
